import itertools, collections, sys

# Bubble group G = Z/9 x Z/2 with N=(0,1); classes H_eta = {(g,0),(0, ant g)}, ant(h,s)=(h,s+1)
Gp=[(h,s) for h in range(9) for s in range(2)]
def ant(g): return (g[0], (g[1]+1)%2)
def gadd(a,b): return ((a[0]+b[0])%9,(a[1]+b[1])%2)
def gneg(a): return ((-a[0])%9,a[1])
def istar(a): return (a[0],(a[1]+1)%2)  # i* = (h, s+1)
def cmul_pair(p,q):
    # (a,b)(c,d) = (ac + b d*, a d + b c)
    (a,b),(c,d)=p,q
    ds=istar(d)
    first=gadd(gmul(a,c),gmul(b,ds))
    scnd=gadd(gmul(a,d),gmul(b,c))
    return (first,scnd)
def gmul(a,b): return ((a[0]*b[0]%9),(a[1]+b[1])%2)

def norm_pair(p):
    a,b=p
    return (a,b) if a<=b else (b,a)
def cls(g):
    return frozenset([norm_pair((g,(0,0))), norm_pair(((0,0),ant(g)))])
CLASSES=list({cls(g) for g in Gp})
IDC=cls((0,0))  # {(g,0),(0,ant(0))} wait: identity class should be {(g,g)}
IDC=frozenset([norm_pair((g,g)) for g in [(0,0)]])  # placeholder, fixed below
# identity: H_1 = {(g, (0,0)), ((0,0), ant g)} with g=(0,0)? No: H_eta for eta=1 is {(g,(h,n)) : ...} with h=0,n=0 i.e. pairs ((g',(0,0)) for g' with h-scale...) Actually H_1 = {(g,g)} per paper param: pairs ( (h,n), (h',n') ) with h=0,n=0 and h'=0,n'=0 => {((0,0),(0,0))} only (diagonal on N). Hmm but for all g? H_eta is a 2-element subset of G"'^2: {(g,(0,0)),((0,0), ant g)} for a fixed g. For eta=1, g=(0,0): H_1 = {((0,0),(0,0))}.
IDC=cls((0,0))
def cls_add(K1,K2):
    out=set()
    for p in K1:
        for q in K2:
            out.add(norm_pair((gadd(p[0],q[0]), gadd(p[1],q[1]))))
    return frozenset(out)
def cls_mul(K1,K2):
    out=set()
    for p in K1:
        for q in K2:
            out.add(norm_pair(cmul_pair(p,q)))
    return frozenset(out)
def cls_neg(K):
    # negate the nonzero slot of each pair
    out=set()
    for (a,b) in K:
        if a==(0,0):
            out.add(norm_pair((a,ant(b))))
        else:
            out.add(norm_pair((ant(a),b)))
    return frozenset(out)

def build_R(U):
    # Universe: {Z} + U-orbits on CLASSES (orbits under cls_mul)
    orbits=[]; seen=set()
    for c in CLASSES:
        if c in seen: continue
        orb=frozenset(cls_mul(u,c) for u in U)
        orbits.append(orb); seen|=orb
    elems=['"'Z']+orbits
    def mulE(e1,e2):
        if e1=='Z' or e2=='Z': return 'Z'
        return frozenset(cls_mul(u,v) for u in e1 for v in e2)
    def addE(e1,e2):
        if e1=='Z': return {e2}
        if e2=='Z': return {e1}
        S=set()
        for a in e1:
            for b in e2:
                t=cls_add(a,b)
                S.add(frozenset(cls_mul(u,t) for u in U))
        return S
    def negE(e):
        if e=='Z': return 'Z'
        c0=next(iter(e))
        nc=cls_neg(c0)
        for f in orbits:
            if nc in f: return f
        raise Exception('neg orbit missing')
    return elems,mulE,addE,negE,orbits

def check_axioms(elems,mulE,addE,negE):
    ok=True
    for a in elems:
        if addE(a,'Z')"'!={a}: print('"'FAIL 0+a'); ok=False
    for b in elems:
        for c in elems:
            S=addE(b,c)
            if ('Z' in S) "'!= (b==negE(c)):
                print('"'FAIL neg<->0in'); ok=False; return ok
    for b in elems:
        for c in elems:
            for a in elems:
                if a in addE(b,c):
                    if b not in addE(a,negE(c)):
                        print('FAIL rev', a,b,c); ok=False
    # weak distributivity + associativity spot check
    for a in elems:
        for b in elems:
            for c in elems:
                L=set()
                for y in addE(b,c): L|=set(addE(a,y))
                R1=set(); R2=set()
                for x in addE(a,b):
                    if x=='Z': R1.add('Z')
                    else: R1.add(mulE(a,x))
                for x in addE(a,c):
                    if x=='Z': R2.add('Z')
                    else: R2.add(mulE(a,x))
                R=set(); 
                for p in R1:
                    for q in R2: R|=set(addE(p,q))
                if not (L<=R):
                    print('FAIL weakdist', a,b,c); ok=False
    return ok

def subgroups():
    subs=set()
    gens=[c for c in CLASSES if c"'!=IDC]
    for r in range(1,4):
        for combo in itertools.combinations(gens,r):
            S={IDC}|set(combo)
            changed=True
            while changed:
                changed=False
                for x in list(S):
                    for y in list(S):
                        z=cls_mul(x,y)
                        if z not in S: S.add(z); changed=True
            if len(S)==4: subs.add(frozenset(S))
    return list(subs)

subs=subgroups()
print('"'order-4 class subgroups:',len(subs))
tot=0; fails=[]; nat_class=collections.Counter(); quadrant_classes=collections.Counter()
for U in subs:
    elems,mulE,addE,negE,orbits=build_R(list(U))
    if not check_axioms(elems,mulE,addE,negE):
        print('U failing axioms skipped'); continue
    nz=[e for e in elems if e"'!='"'Z']
    mem={c:i for i,o in enumerate(orbits) for c in o}
    for a,b,c,d in itertools.product(nz,repeat=4):
        if mulE(a,d)"'!=mulE(b,c): continue
        # mixed pair?
        mixed=False
        for (u,v) in [(a,c),(a,d),(b,c),(b,d)]:
            if addE(u,v)=={mulE(u,v)}: mixed=True;break
        if mixed: continue
        # semi-strong: all sums delta_i+delta_j single-valued and 0-free
        deltas=[mulE(a,b),mulE(a,c),mulE(a,d),mulE(b,c),mulE(b,d),mulE(c,d)]
        ok=True
        for i,x in enumerate(deltas):
            for y in deltas[i:]:
                if len(addE(x,y))!=1 or '"'Z' in addE(x,y): ok=False
        tot+=1
        if not ok:
            fails.append((U,a,b,c,d))
            # classify the failure
        else:
            # natural-isom/quadrant classes of {ab,ac,ad,bc,bd,cd} mod neighbors
            pass
print('total no-mixed ad=bc quadruples:',tot)
print('semi-strong FAILURES:',len(fails))
if fails:
    print(fails[0])
