import itertools

def quotient_hyperfield(p, U):
    Fx=list(range(1,p))
    cosets=[]; seen=set()
    for a in Fx:
        if a in seen: continue
        C=frozenset((a*u)%p for u in U)
        cosets.append(C); seen|=C
    def mul(A,B):
        if A==0 or B==0: return 0
        return frozenset((a*b)%p for a in A for b in B)
    def add(A,B):
        if A==0: return {B}
        if B==0: return {A}
        out=set()
        for a in A:
            for b in B:
                s=(a+b)%p
                out.add(0 if s==0 else frozenset((s*u)%p for u in U))
        return out
    def neg(A):
        if A==0: return 0
        return frozenset((p-a)%p for a in A)
    return [0]+cosets,mul,add,neg

def bigsum(add, terms):
    cur={terms[0]}
    for t in terms[1:]:
        nxt=set()
        for v in cur: nxt|=add(v,t)
        cur=nxt
    return cur

stat={'S18':0,'S15':0,'S12':0,'S9':0,'S6':0,'S3':0,'fail':0,'c2c3nonc1':0,'freehyper':0,'triplecore':0}
ex={}
for p in list(range(5,100))+[101,103,107,109,113,127]:
    pr=p
    if not all(pr%i for i in range(2,int(pr**0.5)+1)): continue
    subgroups=set()
    for g in range(1,p):
        U=set(); a=1
        while a not in U:
            U.add(a); a=(a*g)%p
        subgroups.add(frozenset(U))
    for U in subgroups:
        if len(U) in (1,p-1): continue
        elems,mul,add,neg=quotient_hyperfield(p,sorted(U))
        nz=[e for e in elems if e!=0]
        oneelems=nz
        for x,y,z in itertools.product(nz,repeat=3):
            if 0 not in bigsum(add,[x,y,z]): continue
